// ============================================================================
// Module  : m_vlsit_sfifo_ram_macro
// Purpose : SRAM wrapper of the synchronous-clock FIFO storage: one write port
//           (i_clk_wr, active-low write enable) and one read port (i_clk_rd,
//           active-low read enable) with a registered read data output (read
//           latency of one read-clock cycle). 2^PARA_SFIFO_RAM_ADDR_W rows.
//           A word written at the same edge as it is read is not seen: the
//           read register keeps the old word.
// Spec    : SyncFIFO_Design_Specification.md sections 1.2, 10.5 (MEM-002),
//           14.2, 14.2.1 (m_vlsit_sfifo_ram_macro), 20.1 (OI-003)
// Note    : This wrapper belongs to 000_Common/rtl_lib. The library cell
//           VLSIT_CELL_SRAM_1W1R (and its model) is not available in this
//           work folder, so the body is a behavioural stand-in with the same
//           port contract. When the cell is mapped, the body is replaced by
//           one instance of VLSIT_CELL_SRAM_1W1R named u_dont_touch_sram.
// ============================================================================
`default_nettype none

module m_vlsit_sfifo_ram_macro #(
    // PARA_SFIFO_RAM_ADDR_W: address width of the SRAM (rows = 2^ADDR_W)
    // Legal values: 1 or more
    // Default: 3
    parameter logic [31:0] PARA_SFIFO_RAM_ADDR_W = 3,
    // PARA_SFIFO_RAM_DATA_W: word width of the SRAM in bits
    // Legal values: 1 or more
    // Default: 32
    parameter logic [31:0] PARA_SFIFO_RAM_DATA_W = 32
) (
    // Write port (CLK-WR)
    input  wire                              i_clk_wr,
    input  wire                              i_wr_en_n,
    input  wire  [PARA_SFIFO_RAM_ADDR_W-1:0] i_wr_addr,
    input  wire  [PARA_SFIFO_RAM_DATA_W-1:0] i_wr_data,
    // Read port (CLK-RD)
    input  wire                              i_clk_rd,
    input  wire                              i_rd_en_n,
    input  wire  [PARA_SFIFO_RAM_ADDR_W-1:0] i_rd_addr,
    output logic [PARA_SFIFO_RAM_DATA_W-1:0] o_rd_data
);

  // Number of rows of the macro: 2^ADDR_W (rows above DEPTH-1 are unused)
  localparam logic [31:0] LPARA_RAM_ROWS = 32'd1 << PARA_SFIFO_RAM_ADDR_W;

  // Storage rows: resetless payload
  logic [PARA_SFIFO_RAM_DATA_W-1:0] reg_ram_array [0:LPARA_RAM_ROWS-1];
  // Registered read data (macro output register), not reset
  logic [PARA_SFIFO_RAM_DATA_W-1:0] reg_ram_rd_data;

  // REQ: SF-14.2.1-15, SF-1.2-01
  // Write port: the word is stored at the write clock when i_wr_en_n = 0
  always_ff @(posedge i_clk_wr) begin
    if (!i_wr_en_n) begin
      reg_ram_array[i_wr_addr] <= i_wr_data;
    end
  end

  // REQ: SF-14.2.1-17, SF-10.5-02
  // Read port: address sampled every read cycle, data registered (latency 1)
  always_ff @(posedge i_clk_rd) begin
    if (!i_rd_en_n) begin
      reg_ram_rd_data <= reg_ram_array[i_rd_addr];
    end
  end

  assign o_rd_data = reg_ram_rd_data;

endmodule

`default_nettype wire

// ============================================================================
// Module  : m_vlsit_sfifo_mem
// Purpose : Storage of the synchronous-clock FIFO: PARA_SFIFO_DEPTH words of
//           PARA_SFIFO_DATA_W bits with one write port (CLK-WR) and one read
//           port (CLK-RD) with a read data register (latency one read-clock
//           cycle). Branch selected at elaboration by PARA_SFIFO_MEM_USE_MACRO:
//           0 = pure RTL array, 1 = SRAM wrapper m_vlsit_sfifo_ram_macro.
//           The memory content is not reset (resetless payload).
// Spec    : SyncFIFO_Design_Specification.md sections 5.1, 10.5, 14.2,
//           14.2.1 (m_vlsit_sfifo_mem), 8 (PARA_SFIFO_MEM_USE_MACRO)
// ============================================================================
`default_nettype none

module m_vlsit_sfifo_mem #(
    // PARA_SFIFO_DEPTH: number of FIFO entries
    // Legal values: any integer of 2 or more, no upper limit
    // Default: 8
    parameter logic [31:0] PARA_SFIFO_DEPTH         = 8,
    // PARA_SFIFO_DATA_W: data word width in bits
    // Legal values: 1 or more, no upper limit
    // Default: 32
    parameter logic [31:0] PARA_SFIFO_DATA_W        = 32,
    // PARA_SFIFO_MEM_USE_MACRO: storage branch, 0 = RTL array, 1 = SRAM wrapper
    // Legal values: 0 or 1
    // Default: 0
    parameter logic [31:0] PARA_SFIFO_MEM_USE_MACRO = 0,
    // Derived: memory address width
    localparam logic [31:0] LPARA_ADDR_W = $clog2(PARA_SFIFO_DEPTH)
) (
    // Write port (CLK-WR)
    input  wire                          i_clk_wr,
    input  wire                          i_wr_en,
    input  wire  [LPARA_ADDR_W-1:0]      i_wr_addr,
    input  wire  [PARA_SFIFO_DATA_W-1:0] i_wr_data,
    // Read port (CLK-RD)
    input  wire                          i_clk_rd,
    input  wire  [LPARA_ADDR_W-1:0]      i_rd_addr,
    output logic [PARA_SFIFO_DATA_W-1:0] o_rd_data
);

  // REQ: SF-4-06, SF-8-07, SF-14.2-02
  // Storage branch selected at elaboration (present or absent)
  generate
    if (PARA_SFIFO_MEM_USE_MACRO == 32'd0) begin : g_mem_array
      // REQ: SF-3-12, SF-1.1-11, SF-14.1-03
      // Flop array of DEPTH words, resetless payload
      logic [PARA_SFIFO_DATA_W-1:0] reg_mem_array [0:PARA_SFIFO_DEPTH-1];
      // Memory output register (drives o_rd_data of the top), not reset
      logic [PARA_SFIFO_DATA_W-1:0] reg_mem_rd_data;

      // REQ: SF-14.2.1-11, SF-3-01, SF-3-43
      // Write port: store the word at the write address when enabled
      always_ff @(posedge i_clk_wr) begin
        if (i_wr_en) begin
          reg_mem_array[i_wr_addr] <= i_wr_data;
        end
      end

      // REQ: SF-14.2.1-12, SF-14.2.1-13, SF-10.5-01, SF-10.5-02, SF-3-22
      // Read port: read every read-clock cycle, registered output; a word
      // written at the same edge is not seen (old word kept)
      always_ff @(posedge i_clk_rd) begin
        reg_mem_rd_data <= reg_mem_array[i_rd_addr];
      end

      assign o_rd_data = reg_mem_rd_data;
    end else begin : g_mem_macro
      // REQ: SF-1.2-01, SF-3-56, SF-14.2-02, SF-14.2.1-16, SF-8-08
      // SRAM wrapper: active-low write enable, read enable tied to 0
      m_vlsit_sfifo_ram_macro #(
          .PARA_SFIFO_RAM_ADDR_W (LPARA_ADDR_W),
          .PARA_SFIFO_RAM_DATA_W (PARA_SFIFO_DATA_W)
      ) u_ram_macro (
          .i_clk_wr  (i_clk_wr),
          .i_wr_en_n (~i_wr_en),
          .i_wr_addr (i_wr_addr),
          .i_wr_data (i_wr_data),
          .i_clk_rd  (i_clk_rd),
          .i_rd_en_n (1'b0),
          .i_rd_addr (i_rd_addr),
          .o_rd_data (o_rd_data)
      );
    end
  endgenerate

endmodule

`default_nettype wire

// ============================================================================
// Module  : m_vlsit_sfifo_wr
// Purpose : Write side of the synchronous-clock FIFO (CLK-WR / RST-WR): write
//           pointer (modulo 2 x DEPTH), write acceptance, look-ahead full and
//           full-threshold flags, overflow pulse, memory write port, optional
//           retiming flops of the read pointer and the acknowledge, and the
//           write-side software reset FSM with its request and busy flops.
// Spec    : SyncFIFO_Design_Specification.md sections 5.1, 5.3, 5.4, 6.2,
//           6.3, 7.3, 9, 10.1, 10.2, 10.6, 10.7, 12, 14.2, 14.2.1
// ============================================================================
`default_nettype none

module m_vlsit_sfifo_wr #(
    // PARA_SFIFO_DEPTH: number of FIFO entries
    // Legal values: any integer of 2 or more, no upper limit
    // Default: 8
    parameter logic [31:0] PARA_SFIFO_DEPTH      = 8,
    // PARA_SFIFO_DATA_W: data word width in bits
    // Legal values: 1 or more, no upper limit
    // Default: 32
    parameter logic [31:0] PARA_SFIFO_DATA_W     = 32,
    // PARA_SFIFO_PTR_RETIME: 0 = direct read pointer, 1 = one retiming flop
    // Legal values: 0 or 1
    // Default: 0
    parameter logic [31:0] PARA_SFIFO_PTR_RETIME = 0,
    // Derived: memory address width, pointer width, occupancy width
    localparam logic [31:0] LPARA_ADDR_W = $clog2(PARA_SFIFO_DEPTH),
    localparam logic [31:0] LPARA_PTR_W  = $clog2(2 * PARA_SFIFO_DEPTH),
    localparam logic [31:0] LPARA_OCC_W  = $clog2(PARA_SFIFO_DEPTH + 1)
) (
    // Clock and reset (CLK-WR)
    input  wire                          i_clk_wr,
    input  wire                          i_rst_n_wr,
    // Write interface
    input  wire                          i_wr_en,
    input  wire  [PARA_SFIFO_DATA_W-1:0] i_wr_data,
    input  wire  [LPARA_OCC_W-1:0]       i_full_thr,
    output logic                         o_full,
    output logic                         o_full_thr,
    output logic                         o_overflow,
    // Software reset interface
    input  wire                          i_rst_n_sw,
    output logic                         o_sw_rst_busy,
    // Pointers and handshake with the read side
    input  wire  [LPARA_PTR_W-1:0]       i_rd_ptr,
    output logic [LPARA_PTR_W-1:0]       o_wr_ptr,
    output logic                         o_req_wr,
    input  wire                          i_ack_rd,
    // Memory write port
    output logic                         o_mem_wr_en,
    output logic [LPARA_ADDR_W-1:0]      o_mem_wr_addr,
    output logic [PARA_SFIFO_DATA_W-1:0] o_mem_wr_data
);

  // --------------------------------------------------------------------------
  // Constants
  // --------------------------------------------------------------------------
  localparam logic [31:0] LPARA_TWO_DEPTH = 2 * PARA_SFIFO_DEPTH;
  localparam logic [31:0] LPARA_PTR_LAST  = (2 * PARA_SFIFO_DEPTH) - 1;
  localparam logic [31:0] LPARA_PTR_ONE   = 1;

  // --------------------------------------------------------------------------
  // Write reset FSM states (3 bits, encodings 5 to 7 recover to RUN)
  // --------------------------------------------------------------------------
  typedef enum logic [2:0] {
    ENUM_ST_RUN  = 3'd0,
    ENUM_ST_REQ  = 3'd1,
    ENUM_ST_PTR  = 3'd2,
    ENUM_ST_HOLD = 3'd3,
    ENUM_ST_REL  = 3'd4
  } t_fsm_srst_wr_e;

  t_fsm_srst_wr_e reg_fsm_srst_current_state;
  t_fsm_srst_wr_e w_fsm_srst_nxt_state;

  // --------------------------------------------------------------------------
  // Signals
  // --------------------------------------------------------------------------
  logic [LPARA_PTR_W-1:0] reg_wr_ptr;
  logic [LPARA_PTR_W-1:0] w_wr_ptr_inc;
  logic [LPARA_PTR_W-1:0] w_wr_ptr_nxt;
  logic [LPARA_PTR_W-1:0] w_rd_ptr_view;
  logic                   w_ack_view;
  logic [LPARA_PTR_W:0]   w_occ_nxt;
  logic [LPARA_PTR_W:0]   w_full_thr_ext;
  logic                   reg_full;
  logic                   reg_full_thr;
  logic                   reg_overflow;
  logic                   reg_sw_rst_busy;
  logic                   reg_req;
  logic                   reg_sw_rst_pend;
  logic                   reg_sw_rst_req_d;
  logic                   w_sw_rst_pend_nxt;
  logic                   w_sw_rst_fall;
  logic                   w_block;
  logic                   w_wr_accept;
  logic                   w_full_thr_blk;

  // --------------------------------------------------------------------------
  // View of the read pointer and the acknowledge (timed paths, no synchronizer)
  // --------------------------------------------------------------------------
  // REQ: SF-1.1-04, SF-1.1-12, SF-3-24, SF-3-25, SF-3-26, SF-3-27, SF-3-28
  // REQ: SF-3-57, SF-14.2.1-01, SF-4-06
  generate
    if (PARA_SFIFO_PTR_RETIME != 32'd0) begin : g_rd_ptr_retime
      // One plain retiming flop per crossing signal in the destination domain
      logic [LPARA_PTR_W-1:0] reg_rd_ptr_rt;
      logic                   reg_ack_rt;

      always_ff @(posedge i_clk_wr or negedge i_rst_n_wr) begin
        if (!i_rst_n_wr) begin
          reg_rd_ptr_rt <= '0;
          reg_ack_rt    <= 1'b0;
        end else begin
          reg_rd_ptr_rt <= i_rd_ptr;
          reg_ack_rt    <= i_ack_rd;
        end
      end

      assign w_rd_ptr_view = reg_rd_ptr_rt;
      assign w_ack_view    = reg_ack_rt;
    end else begin : g_rd_ptr_direct
      // Direct path into the flag logic
      assign w_rd_ptr_view = i_rd_ptr;
      assign w_ack_view    = i_ack_rd;
    end
  endgenerate

  // --------------------------------------------------------------------------
  // Software reset block term and write acceptance
  // --------------------------------------------------------------------------
  // REQ: SF-3-35, SF-3-36, SF-10.7-01, SF-6.3-11, SF-12-07
  // Block with no clock delay from i_rst_n_sw = 0; held by the busy flop.
  // A pending new request (REQ-SRST-008) also blocks in its RUN cycle.
  assign w_block = reg_sw_rst_busy | ~i_rst_n_sw | reg_sw_rst_pend;

  // REQ: SF-3-01, SF-6.3-01, SF-3-07, SF-5.4-02, SF-20.2-05, SF-10.1-01
  // Accepted only if the own full flag allows it (no bypass)
  assign w_wr_accept = i_wr_en & ~w_block & ~reg_full;

  // --------------------------------------------------------------------------
  // Write pointer (modulo 2 x DEPTH)
  // --------------------------------------------------------------------------
  // REQ: SF-3-13, SF-9-01, SF-8-10
  assign w_wr_ptr_inc = (reg_wr_ptr == LPARA_PTR_LAST[LPARA_PTR_W-1:0])
                      ? '0
                      : (reg_wr_ptr + LPARA_PTR_ONE[LPARA_PTR_W-1:0]);

  // REQ: SF-5.3-01, SF-3-19, SF-10.1-04, SF-10.7-04
  always_comb begin
    w_wr_ptr_nxt = reg_wr_ptr;
    if (reg_fsm_srst_current_state == ENUM_ST_PTR) begin
      w_wr_ptr_nxt = '0;
    end else if (w_wr_accept) begin
      w_wr_ptr_nxt = w_wr_ptr_inc;
    end
  end

  // --------------------------------------------------------------------------
  // Look-ahead occupancy of the write view: occ(next write ptr, rd_ptr_view)
  // --------------------------------------------------------------------------
  // REQ: SF-9-03, SF-5.4-01, SF-5.1-01, SF-5.4-04, SF-6.3-05
  assign w_occ_nxt = (w_wr_ptr_nxt >= w_rd_ptr_view)
                   ? ({1'b0, w_wr_ptr_nxt} - {1'b0, w_rd_ptr_view})
                   : ({1'b0, w_wr_ptr_nxt} + LPARA_TWO_DEPTH[LPARA_PTR_W:0]
                      - {1'b0, w_rd_ptr_view});

  // REQ: SF-9-06, SF-9-05
  // Threshold zero-extended for the comparison
  assign w_full_thr_ext = {{(LPARA_PTR_W + 1 - LPARA_OCC_W){1'b0}}, i_full_thr};

  // --------------------------------------------------------------------------
  // Pointer, flag and pulse flops
  // --------------------------------------------------------------------------
  // REQ: SF-3-05, SF-3-14, SF-3-17, SF-3-54, SF-10.6-02, SF-10.6-04, SF-3-29
  // REQ: SF-3-30, SF-7.3-01, SF-7.3-05, SF-10.6-10, SF-6.2-06, SF-12-11
  // REQ: SF-14.2.1-02, SF-10.2-01, SF-10.2-05, SF-6.3-08, SF-12-01, SF-3-37
  always_ff @(posedge i_clk_wr or negedge i_rst_n_wr) begin
    if (!i_rst_n_wr) begin
      reg_wr_ptr   <= '0;
      reg_full     <= 1'b0;
      reg_full_thr <= 1'b0;
      reg_overflow <= 1'b0;
    end else begin
      reg_wr_ptr   <= w_wr_ptr_nxt;
      reg_full     <= (w_occ_nxt == PARA_SFIFO_DEPTH[LPARA_PTR_W:0]);
      reg_full_thr <= (w_occ_nxt >= w_full_thr_ext);
      reg_overflow <= i_wr_en & ~w_block & reg_full;
    end
  end

  // --------------------------------------------------------------------------
  // Write reset FSM (four-phase handshake, write side)
  // --------------------------------------------------------------------------
  // REQ: SF-10.1-02, SF-10.1-03, SF-10.1-04, SF-10.1-05, SF-3-33, SF-3-34
  // REQ: SF-3-40, SF-3-41, SF-1.1-14, SF-10.7-02, SF-10.7-04, SF-10.7-06
  // REQ: SF-10.7-08, SF-3-47, SF-3-48, SF-10.7-10
  always_comb begin
    w_fsm_srst_nxt_state = reg_fsm_srst_current_state;
    case (reg_fsm_srst_current_state)
      ENUM_ST_RUN: begin
        if (!i_rst_n_sw || reg_sw_rst_pend) begin
          w_fsm_srst_nxt_state = ENUM_ST_REQ;
        end
      end
      ENUM_ST_REQ: begin
        if (w_ack_view) begin
          w_fsm_srst_nxt_state = ENUM_ST_PTR;
        end
      end
      ENUM_ST_PTR: begin
        w_fsm_srst_nxt_state = ENUM_ST_HOLD;
      end
      ENUM_ST_HOLD: begin
        if (i_rst_n_sw) begin
          w_fsm_srst_nxt_state = ENUM_ST_REL;
        end
      end
      ENUM_ST_REL: begin
        // Flush check: acknowledge 0 and read pointer seen as 0
        if (!w_ack_view && (w_rd_ptr_view == '0)) begin
          w_fsm_srst_nxt_state = ENUM_ST_RUN;
        end
      end
      default: begin
        w_fsm_srst_nxt_state = ENUM_ST_RUN;
      end
    endcase
  end

  // REQ: SF-3-47, SF-10.7-10
  // A new request that arrives while a sequence runs (a low level in REL, or
  // a new falling edge in REQ or PTR) is remembered and served from RUN.
  assign w_sw_rst_fall = ~i_rst_n_sw & ~reg_sw_rst_req_d;

  always_comb begin
    w_sw_rst_pend_nxt = reg_sw_rst_pend;
    case (reg_fsm_srst_current_state)
      ENUM_ST_RUN: begin
        w_sw_rst_pend_nxt = 1'b0;
      end
      ENUM_ST_REQ, ENUM_ST_PTR: begin
        w_sw_rst_pend_nxt = reg_sw_rst_pend | w_sw_rst_fall;
      end
      ENUM_ST_HOLD: begin
        w_sw_rst_pend_nxt = reg_sw_rst_pend;
      end
      ENUM_ST_REL: begin
        w_sw_rst_pend_nxt = reg_sw_rst_pend | ~i_rst_n_sw;
      end
      default: begin
        w_sw_rst_pend_nxt = 1'b0;
      end
    endcase
  end

  // REQ: SF-3-44, SF-6.2-02, SF-14.2.1-06, SF-3-46, SF-7.3-08, SF-10.7-09
  // FSM, busy, request and handshake flops; hardware reset has priority
  always_ff @(posedge i_clk_wr or negedge i_rst_n_wr) begin
    if (!i_rst_n_wr) begin
      reg_fsm_srst_current_state <= ENUM_ST_RUN;
      reg_sw_rst_busy            <= 1'b0;
      reg_req                    <= 1'b0;
      reg_sw_rst_pend            <= 1'b0;
      reg_sw_rst_req_d           <= 1'b0;
    end else begin
      reg_fsm_srst_current_state <= w_fsm_srst_nxt_state;
      // Busy: 1 from the cycle after the request is taken until back in RUN
      reg_sw_rst_busy            <= (w_fsm_srst_nxt_state != ENUM_ST_RUN);
      // Request: set with busy, cleared when REL starts
      reg_req                    <= (w_fsm_srst_nxt_state == ENUM_ST_REQ)
                                  | (w_fsm_srst_nxt_state == ENUM_ST_PTR)
                                  | (w_fsm_srst_nxt_state == ENUM_ST_HOLD);
      reg_sw_rst_pend            <= w_sw_rst_pend_nxt;
      reg_sw_rst_req_d           <= ~i_rst_n_sw;
    end
  end

  // --------------------------------------------------------------------------
  // Outputs
  // --------------------------------------------------------------------------
  // REQ: SF-3-21, SF-10.6-03, SF-3-35
  // Flag flops combined with the block term by one gate
  assign w_full_thr_blk = (i_full_thr == '0);
  assign o_full         = w_block | reg_full;
  assign o_full_thr     = w_block ? w_full_thr_blk : reg_full_thr;
  assign o_overflow     = reg_overflow;
  assign o_sw_rst_busy  = reg_sw_rst_busy;

  // REQ: SF-14.2.1-02, SF-14.2.1-06
  assign o_wr_ptr = reg_wr_ptr;
  assign o_req_wr = reg_req;

  // REQ: SF-14.2.1-03, SF-14.2.1-04, SF-14.2.1-05, SF-3-13
  // Memory write port: address = write pointer modulo DEPTH
  assign o_mem_wr_en   = w_wr_accept;
  assign o_mem_wr_addr = (reg_wr_ptr >= PARA_SFIFO_DEPTH[LPARA_PTR_W-1:0])
                       ? (reg_wr_ptr[LPARA_ADDR_W-1:0]
                          - PARA_SFIFO_DEPTH[LPARA_ADDR_W-1:0])
                       : reg_wr_ptr[LPARA_ADDR_W-1:0];
  assign o_mem_wr_data = i_wr_data;

endmodule

`default_nettype wire

// ============================================================================
// Module  : m_vlsit_sfifo_rd
// Purpose : Read side of the synchronous-clock FIFO (CLK-RD / RST-RD): read
//           pointer (modulo 2 x DEPTH), read acceptance, look-ahead empty and
//           empty-threshold flags, underflow pulse, memory read address (the
//           address of the next read pointer, show-ahead), optional retiming
//           flops of the write pointer and the request, and the read-side
//           software reset FSM with its acknowledge flop.
// Spec    : SyncFIFO_Design_Specification.md sections 5.1, 5.3, 5.4, 6.2,
//           6.3, 7.3, 9, 10.1, 10.2, 10.5, 10.6, 10.7, 12, 14.2, 14.2.1
// ============================================================================
`default_nettype none

module m_vlsit_sfifo_rd #(
    // PARA_SFIFO_DEPTH: number of FIFO entries
    // Legal values: any integer of 2 or more, no upper limit
    // Default: 8
    parameter logic [31:0] PARA_SFIFO_DEPTH      = 8,
    // PARA_SFIFO_DATA_W: data word width in bits
    // Legal values: 1 or more, no upper limit
    // Default: 32
    parameter logic [31:0] PARA_SFIFO_DATA_W     = 32,
    // PARA_SFIFO_PTR_RETIME: 0 = direct write pointer, 1 = one retiming flop
    // Legal values: 0 or 1
    // Default: 0
    parameter logic [31:0] PARA_SFIFO_PTR_RETIME = 0,
    // Derived: memory address width, pointer width, occupancy width
    localparam logic [31:0] LPARA_ADDR_W = $clog2(PARA_SFIFO_DEPTH),
    localparam logic [31:0] LPARA_PTR_W  = $clog2(2 * PARA_SFIFO_DEPTH),
    localparam logic [31:0] LPARA_OCC_W  = $clog2(PARA_SFIFO_DEPTH + 1)
) (
    // Clock and reset (CLK-RD)
    input  wire                          i_clk_rd,
    input  wire                          i_rst_n_rd,
    // Read interface
    input  wire                          i_rd_en,
    input  wire  [LPARA_OCC_W-1:0]       i_empty_thr,
    output logic [PARA_SFIFO_DATA_W-1:0] o_rd_data,
    output logic                         o_empty,
    output logic                         o_empty_thr,
    output logic                         o_underflow,
    // Pointers and handshake with the write side
    input  wire  [LPARA_PTR_W-1:0]       i_wr_ptr,
    output logic [LPARA_PTR_W-1:0]       o_rd_ptr,
    input  wire                          i_req_wr,
    output logic                         o_ack_rd,
    // Memory read port
    output logic [LPARA_ADDR_W-1:0]      o_mem_rd_addr,
    input  wire  [PARA_SFIFO_DATA_W-1:0] i_mem_rd_data
);

  // --------------------------------------------------------------------------
  // Constants
  // --------------------------------------------------------------------------
  localparam logic [31:0] LPARA_TWO_DEPTH = 2 * PARA_SFIFO_DEPTH;
  localparam logic [31:0] LPARA_PTR_LAST  = (2 * PARA_SFIFO_DEPTH) - 1;
  localparam logic [31:0] LPARA_PTR_ONE   = 1;

  // --------------------------------------------------------------------------
  // Read reset FSM states (2 bits, encoding 3 recovers to RUN)
  // --------------------------------------------------------------------------
  typedef enum logic [1:0] {
    ENUM_ST_RUN = 2'd0,
    ENUM_ST_RST = 2'd1,
    ENUM_ST_ACK = 2'd2
  } t_fsm_srst_rd_e;

  t_fsm_srst_rd_e reg_fsm_srst_current_state;
  t_fsm_srst_rd_e w_fsm_srst_nxt_state;

  // --------------------------------------------------------------------------
  // Signals
  // --------------------------------------------------------------------------
  logic [LPARA_PTR_W-1:0] reg_rd_ptr;
  logic [LPARA_PTR_W-1:0] w_rd_ptr_inc;
  logic [LPARA_PTR_W-1:0] w_rd_ptr_nxt;
  logic [LPARA_PTR_W-1:0] w_wr_ptr_view;
  logic                   w_req_view;
  logic [LPARA_PTR_W:0]   w_occ_nxt;
  logic [LPARA_PTR_W:0]   w_empty_thr_ext;
  logic                   reg_empty;
  logic                   reg_empty_thr;
  logic                   reg_underflow;
  logic                   reg_ack;
  logic                   w_block;
  logic                   w_rd_accept;

  // --------------------------------------------------------------------------
  // View of the write pointer and the request (timed paths, no synchronizer)
  // --------------------------------------------------------------------------
  // REQ: SF-1.1-04, SF-1.1-12, SF-3-24, SF-3-25, SF-3-26, SF-3-27, SF-3-28
  // REQ: SF-3-57, SF-14.2.1-01, SF-4-06, SF-5.3-02
  generate
    if (PARA_SFIFO_PTR_RETIME != 32'd0) begin : g_wr_ptr_retime
      // One plain retiming flop per crossing signal in the destination domain
      logic [LPARA_PTR_W-1:0] reg_wr_ptr_rt;
      logic                   reg_req_rt;

      always_ff @(posedge i_clk_rd or negedge i_rst_n_rd) begin
        if (!i_rst_n_rd) begin
          reg_wr_ptr_rt <= '0;
          reg_req_rt    <= 1'b0;
        end else begin
          reg_wr_ptr_rt <= i_wr_ptr;
          reg_req_rt    <= i_req_wr;
        end
      end

      assign w_wr_ptr_view = reg_wr_ptr_rt;
      assign w_req_view    = reg_req_rt;
    end else begin : g_wr_ptr_direct
      // Direct path into the flag logic
      assign w_wr_ptr_view = i_wr_ptr;
      assign w_req_view    = i_req_wr;
    end
  endgenerate

  // --------------------------------------------------------------------------
  // Software reset block term and read acceptance
  // --------------------------------------------------------------------------
  // REQ: SF-3-38, SF-3-39, SF-10.7-03, SF-6.3-11, SF-12-07
  // Block: request seen on the read side OR read FSM not in RUN
  assign w_block = w_req_view | (reg_fsm_srst_current_state != ENUM_ST_RUN);

  // REQ: SF-3-02, SF-6.3-03, SF-3-11, SF-5.4-02, SF-10.1-01
  // Accepted only if the own empty flag allows it
  assign w_rd_accept = i_rd_en & ~w_block & ~reg_empty;

  // --------------------------------------------------------------------------
  // Read pointer (modulo 2 x DEPTH)
  // --------------------------------------------------------------------------
  // REQ: SF-3-13, SF-9-01, SF-8-10
  assign w_rd_ptr_inc = (reg_rd_ptr == LPARA_PTR_LAST[LPARA_PTR_W-1:0])
                      ? '0
                      : (reg_rd_ptr + LPARA_PTR_ONE[LPARA_PTR_W-1:0]);

  // REQ: SF-5.3-04, SF-3-19, SF-10.1-07, SF-10.7-03
  always_comb begin
    w_rd_ptr_nxt = reg_rd_ptr;
    if (reg_fsm_srst_current_state == ENUM_ST_RST) begin
      w_rd_ptr_nxt = '0;
    end else if (w_rd_accept) begin
      w_rd_ptr_nxt = w_rd_ptr_inc;
    end
  end

  // --------------------------------------------------------------------------
  // Look-ahead occupancy of the read view: occ(wr_ptr_view, next read ptr)
  // --------------------------------------------------------------------------
  // REQ: SF-9-03, SF-5.4-01, SF-5.1-01, SF-5.4-04, SF-6.3-05
  assign w_occ_nxt = (w_wr_ptr_view >= w_rd_ptr_nxt)
                   ? ({1'b0, w_wr_ptr_view} - {1'b0, w_rd_ptr_nxt})
                   : ({1'b0, w_wr_ptr_view} + LPARA_TWO_DEPTH[LPARA_PTR_W:0]
                      - {1'b0, w_rd_ptr_nxt});

  // REQ: SF-9-06, SF-9-05
  // Threshold zero-extended for the comparison
  assign w_empty_thr_ext = {{(LPARA_PTR_W + 1 - LPARA_OCC_W){1'b0}}, i_empty_thr};

  // --------------------------------------------------------------------------
  // Pointer, flag and pulse flops
  // --------------------------------------------------------------------------
  // REQ: SF-3-08, SF-3-15, SF-3-18, SF-3-54, SF-10.6-05, SF-10.6-07, SF-3-29
  // REQ: SF-3-30, SF-7.3-02, SF-7.3-05, SF-6.2-06, SF-12-11, SF-14.2.1-07
  // REQ: SF-10.2-03, SF-10.2-06, SF-6.3-10, SF-12-04, SF-5.3-03, SF-3-52
  always_ff @(posedge i_clk_rd or negedge i_rst_n_rd) begin
    if (!i_rst_n_rd) begin
      reg_rd_ptr    <= '0;
      reg_empty     <= 1'b1;
      reg_empty_thr <= 1'b1;
      reg_underflow <= 1'b0;
    end else begin
      reg_rd_ptr    <= w_rd_ptr_nxt;
      reg_empty     <= (w_occ_nxt == '0);
      reg_empty_thr <= (w_occ_nxt <= w_empty_thr_ext);
      reg_underflow <= i_rd_en & ~w_block & reg_empty;
    end
  end

  // --------------------------------------------------------------------------
  // Read reset FSM (four-phase handshake, read side)
  // --------------------------------------------------------------------------
  // REQ: SF-10.1-06, SF-10.1-07, SF-10.1-08, SF-3-40, SF-3-41, SF-1.1-14
  // REQ: SF-10.7-03, SF-10.7-05
  always_comb begin
    w_fsm_srst_nxt_state = reg_fsm_srst_current_state;
    case (reg_fsm_srst_current_state)
      ENUM_ST_RUN: begin
        if (w_req_view) begin
          w_fsm_srst_nxt_state = ENUM_ST_RST;
        end
      end
      ENUM_ST_RST: begin
        w_fsm_srst_nxt_state = ENUM_ST_ACK;
      end
      ENUM_ST_ACK: begin
        // Flush check: request 0 and write pointer seen as 0
        if (!w_req_view && (w_wr_ptr_view == '0)) begin
          w_fsm_srst_nxt_state = ENUM_ST_RUN;
        end
      end
      default: begin
        w_fsm_srst_nxt_state = ENUM_ST_RUN;
      end
    endcase
  end

  // REQ: SF-14.2.1-10, SF-3-46, SF-7.3-08, SF-10.7-09
  // FSM and acknowledge flops; acknowledge 1 from leaving RST to leaving ACK
  always_ff @(posedge i_clk_rd or negedge i_rst_n_rd) begin
    if (!i_rst_n_rd) begin
      reg_fsm_srst_current_state <= ENUM_ST_RUN;
      reg_ack                    <= 1'b0;
    end else begin
      reg_fsm_srst_current_state <= w_fsm_srst_nxt_state;
      reg_ack                    <= (w_fsm_srst_nxt_state == ENUM_ST_ACK);
    end
  end

  // --------------------------------------------------------------------------
  // Outputs
  // --------------------------------------------------------------------------
  // REQ: SF-3-21, SF-10.6-06, SF-3-38
  // Flag flops combined with the block term by one gate
  assign o_empty     = w_block | reg_empty;
  assign o_empty_thr = w_block | reg_empty_thr;
  assign o_underflow = reg_underflow;

  // REQ: SF-14.2.1-07, SF-14.2.1-10
  assign o_rd_ptr = reg_rd_ptr;
  assign o_ack_rd = reg_ack;

  // REQ: SF-14.2.1-08, SF-10.5-01, SF-3-03, SF-6.3-04, SF-3-13
  // Memory read address: next read pointer modulo DEPTH (show-ahead)
  assign o_mem_rd_addr = (w_rd_ptr_nxt >= PARA_SFIFO_DEPTH[LPARA_PTR_W-1:0])
                       ? (w_rd_ptr_nxt[LPARA_ADDR_W-1:0]
                          - PARA_SFIFO_DEPTH[LPARA_ADDR_W-1:0])
                       : w_rd_ptr_nxt[LPARA_ADDR_W-1:0];

  // REQ: SF-3-22, SF-14.2.1-09, SF-20.2-01, SF-3-10
  // o_rd_data is the memory output register, no logic after it
  assign o_rd_data = i_mem_rd_data;

endmodule

`default_nettype wire

// ============================================================================
// Module  : m_vlsit_sfifo_top
// Purpose : Structural top of the synchronous-clock FIFO: ports, parameters,
//           interconnect and the three instances u_wr (write side, CLK-WR),
//           u_rd (read side, CLK-RD) and u_mem (storage). The two clocks are
//           synchronous (one source, fixed phase); the pointers and the
//           software reset handshake cross as timed paths, no synchronizer.
// Spec    : SyncFIFO_Design_Specification.md sections 1.1, 4, 5.1, 5.2, 6.2,
//           7.1, 7.2, 8, 14.2
// ============================================================================
`default_nettype none

module m_vlsit_sfifo_top #(
    // PARA_SFIFO_DEPTH: number of FIFO entries (not only a power of two)
    // Legal values: any integer of 2 or more, no upper limit
    // Default: 8
    parameter logic [31:0] PARA_SFIFO_DEPTH         = 8,
    // PARA_SFIFO_DATA_W: data word width in bits
    // Legal values: 1 or more, no upper limit
    // Default: 32
    parameter logic [31:0] PARA_SFIFO_DATA_W        = 32,
    // PARA_SFIFO_PTR_RETIME: pointer path, 0 = direct, 1 = one retiming flop
    // Legal values: 0 or 1
    // Default: 0
    parameter logic [31:0] PARA_SFIFO_PTR_RETIME    = 0,
    // PARA_SFIFO_MEM_USE_MACRO: storage, 0 = RTL array, 1 = SRAM wrapper
    // Legal values: 0 or 1
    // Default: 0
    parameter logic [31:0] PARA_SFIFO_MEM_USE_MACRO = 0,
    // REQ: SF-8-09, SF-8-10, SF-8-11
    // Derived: memory address width, pointer width, occupancy width
    localparam logic [31:0] LPARA_ADDR_W = $clog2(PARA_SFIFO_DEPTH),
    localparam logic [31:0] LPARA_PTR_W  = $clog2(2 * PARA_SFIFO_DEPTH),
    localparam logic [31:0] LPARA_OCC_W  = $clog2(PARA_SFIFO_DEPTH + 1)
) (
    // REQ: SF-3-20, SF-4-07, SF-6.2-01, SF-6.1-01, SF-6.1-02, SF-6.1-03
    // REQ: SF-6.1-04
    // Write domain (CLK-WR)
    input  wire                          i_clk_wr,
    input  wire                          i_rst_n_wr,
    input  wire                          i_wr_en,
    input  wire  [PARA_SFIFO_DATA_W-1:0] i_wr_data,
    input  wire  [LPARA_OCC_W-1:0]       i_full_thr,
    input  wire                          i_rst_n_sw,
    output logic                         o_sw_rst_busy,
    output logic                         o_full,
    output logic                         o_full_thr,
    output logic                         o_overflow,
    // Read domain (CLK-RD)
    input  wire                          i_clk_rd,
    input  wire                          i_rst_n_rd,
    input  wire                          i_rd_en,
    input  wire  [LPARA_OCC_W-1:0]       i_empty_thr,
    output logic [PARA_SFIFO_DATA_W-1:0] o_rd_data,
    output logic                         o_empty,
    output logic                         o_empty_thr,
    output logic                         o_underflow
);

  // --------------------------------------------------------------------------
  // Interconnect
  // --------------------------------------------------------------------------
  logic [LPARA_PTR_W-1:0]       w_wr_ptr;
  logic [LPARA_PTR_W-1:0]       w_rd_ptr;
  logic                         w_req_wr;
  logic                         w_ack_rd;
  logic                         w_mem_wr_en;
  logic [LPARA_ADDR_W-1:0]      w_mem_wr_addr;
  logic [PARA_SFIFO_DATA_W-1:0] w_mem_wr_data;
  logic [LPARA_ADDR_W-1:0]      w_mem_rd_addr;
  logic [PARA_SFIFO_DATA_W-1:0] w_mem_rd_data;

  // --------------------------------------------------------------------------
  // Write side (CLK-WR)
  // --------------------------------------------------------------------------
  // REQ: SF-14.2-01, SF-14.2-03, SF-3-55, SF-1.1-01, SF-1.1-06, SF-1.3-01
  m_vlsit_sfifo_wr #(
      .PARA_SFIFO_DEPTH      (PARA_SFIFO_DEPTH),
      .PARA_SFIFO_DATA_W     (PARA_SFIFO_DATA_W),
      .PARA_SFIFO_PTR_RETIME (PARA_SFIFO_PTR_RETIME)
  ) u_wr (
      .i_clk_wr      (i_clk_wr),
      .i_rst_n_wr    (i_rst_n_wr),
      .i_wr_en       (i_wr_en),
      .i_wr_data     (i_wr_data),
      .i_full_thr    (i_full_thr),
      .o_full        (o_full),
      .o_full_thr    (o_full_thr),
      .o_overflow    (o_overflow),
      .i_rst_n_sw    (i_rst_n_sw),
      .o_sw_rst_busy (o_sw_rst_busy),
      .i_rd_ptr      (w_rd_ptr),
      .o_wr_ptr      (w_wr_ptr),
      .o_req_wr      (w_req_wr),
      .i_ack_rd      (w_ack_rd),
      .o_mem_wr_en   (w_mem_wr_en),
      .o_mem_wr_addr (w_mem_wr_addr),
      .o_mem_wr_data (w_mem_wr_data)
  );

  // --------------------------------------------------------------------------
  // Read side (CLK-RD)
  // --------------------------------------------------------------------------
  // REQ: SF-14.2-01, SF-14.2-03, SF-1.1-02, SF-1.3-05
  m_vlsit_sfifo_rd #(
      .PARA_SFIFO_DEPTH      (PARA_SFIFO_DEPTH),
      .PARA_SFIFO_DATA_W     (PARA_SFIFO_DATA_W),
      .PARA_SFIFO_PTR_RETIME (PARA_SFIFO_PTR_RETIME)
  ) u_rd (
      .i_clk_rd      (i_clk_rd),
      .i_rst_n_rd    (i_rst_n_rd),
      .i_rd_en       (i_rd_en),
      .i_empty_thr   (i_empty_thr),
      .o_rd_data     (o_rd_data),
      .o_empty       (o_empty),
      .o_empty_thr   (o_empty_thr),
      .o_underflow   (o_underflow),
      .i_wr_ptr      (w_wr_ptr),
      .o_rd_ptr      (w_rd_ptr),
      .i_req_wr      (w_req_wr),
      .o_ack_rd      (w_ack_rd),
      .o_mem_rd_addr (w_mem_rd_addr),
      .i_mem_rd_data (w_mem_rd_data)
  );

  // --------------------------------------------------------------------------
  // Storage (write port CLK-WR, read port CLK-RD)
  // --------------------------------------------------------------------------
  // REQ: SF-14.2-01, SF-3-04, SF-1.2-01
  m_vlsit_sfifo_mem #(
      .PARA_SFIFO_DEPTH         (PARA_SFIFO_DEPTH),
      .PARA_SFIFO_DATA_W        (PARA_SFIFO_DATA_W),
      .PARA_SFIFO_MEM_USE_MACRO (PARA_SFIFO_MEM_USE_MACRO)
  ) u_mem (
      .i_clk_wr  (i_clk_wr),
      .i_wr_en   (w_mem_wr_en),
      .i_wr_addr (w_mem_wr_addr),
      .i_wr_data (w_mem_wr_data),
      .i_clk_rd  (i_clk_rd),
      .i_rd_addr (w_mem_rd_addr),
      .o_rd_data (w_mem_rd_data)
  );

endmodule

`default_nettype wire
